import subprocess,re
branches=['rachel','monica','phoebe','joey','chandler','ross']
pat=re.compile(rb'Friend-Message: 1')
counts={}
shas={}
for b in branches:
    out=subprocess.check_output(['git','log','--format=%H%x00%ci%x00%B%x1e',f'origin/friend/{b}'], text=True, errors='replace')
    for rec in out.split('\x1e'):
        if not rec.strip(): continue
        parts=rec.split('\x00',2)
        sha,ci,msg=parts[0],parts[1],parts[2]
        if 'Friend-Message: 1' in msg:
            m=re.search(r'Episode:\s*(.+)',msg)
            ep=m.group(1).strip() if m else '?'
            counts[ep]=counts.get(ep,0)+1
            shas.setdefault(ep,[]).append((b,sha,ci.strip()))
print('counts by episode (all branches):')
for ep in sorted(counts): print(ep, counts[ep])
print('S03/E23 commits:')
for x in sorted(shas.get('S03/E23',[]), key=lambda t:t[2]): print(x)
